"""Exact-case planning protocol for the C125751 signal-controlled crossing.

These are requested capture conditions. The original-frame saved audit decides
what happened; no authored value is used as a measured or legal outcome.
"""
from __future__ import annotations

import json
from pathlib import Path


ASSIGNMENT = 'testing__C125751__NRS-484B-250-1__motor_vehicle_driver'
SUFFIXES = ('precedence', 'advance', 'other_later', 'signal_red')
FIXED = ('law_id', 'cell_id', 'actor', 'layout', 'maneuver', 'control',
         'source_packet_sha256', 'map_sha256', 'crossing_id',
         'ego_route_sha256', 'other_route_sha256', 'camera_plan_sha256',
         'duration_frames', 'ego_blueprint', 'other_blueprint')
EXPECTED = {
    'precedence': (True, 'Green', 'yield'),
    'advance': (True, 'Green', 'advance'),
    'other_later': (False, 'Green', 'yield'),
    'signal_red': (True, 'Red', 'yield'),
}
COMPARISONS = {
    'median_entry_order': ('precedence', 'other_later', 'other_first'),
    'official_signal_readback': ('precedence', 'signal_red', 'ego_light_request'),
}


def load_case(folder: Path, suffix: str) -> dict:
    if suffix not in SUFFIXES:
        raise ValueError('undefined exact case')
    return json.loads((folder / 'cases' / suffix / 'case-spec.json').read_text())


def validate_case(spec: dict, suffix: str, *, require_source: bool = True):
    if suffix not in SUFFIXES or spec.get('case_id') != ASSIGNMENT + '__' + suffix:
        raise ValueError('exact case identity differs')
    for key, expected in (('law_id', 'NRS-484B-250-1'), ('cell_id', 'C125751'),
                          ('actor', 'motor_vehicle_driver'), ('layout', 'median_opening'),
                          ('maneuver', 'travel'), ('control', 'traffic_light')):
        if spec.get(key) != expected:
            raise ValueError('fixed cell identity differs: ' + key)
    if (spec.get('other_first'), spec.get('ego_light_request'),
            spec.get('ego_response_request')) != EXPECTED[suffix]:
        raise ValueError('case request differs from declared variant')
    if spec.get('source_status') != 'original_review_required':
        raise ValueError('source review boundary absent')
    if require_source:
        for key in FIXED[6:]:
            if not spec.get(key):
                raise ValueError('source or capture binding absent: ' + key)
    if spec.get('rate_hz') != 20 or spec.get('duration_frames') != 1100:
        raise ValueError('shared 20 Hz capture contract differs')
    return spec


def validate_comparison(left: dict, right: dict, comparison_id: str):
    if comparison_id not in COMPARISONS:
        raise ValueError('undefined comparison')
    a, b, variable = COMPARISONS[comparison_id]
    validate_case(left, a)
    validate_case(right, b)
    for key in FIXED:
        if left[key] != right[key]:
            raise ValueError('fixed condition changed: ' + key)
    changed = {key for key in ('other_first', 'ego_light_request')
               if left[key] != right[key]}
    if changed != {variable}:
        raise ValueError('comparison variable not isolated')
    return {'comparison_id': comparison_id,
            'case_ids': [left['case_id'], right['case_id']],
            'changed_request': variable,
            'measured_outcome_pending': True}

"""Source-bound median-opening construction preflight and fail-closed controller.

CARLA remains an injected runtime dependency; this module is CPU importable.
"""
from __future__ import annotations

import hashlib
import json
import math


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _xy(point):
    return (float(point[0]), float(point[1]))


def _inside(point, box):
    x, y = _xy(point)
    x0, y0, x1, y1 = map(float, box)
    return x0 <= x <= x1 and y0 <= y <= y1


def validate_source_packet(packet: dict, map_bytes: bytes, review_bytes: bytes):
    """Reject unsourced crossing, road, device and driver facts before spawning."""
    if packet.get('schema') != 'median-signal-review-v1':
        raise ValueError('unreviewed packet schema')
    if packet.get('map_sha256') != sha256(map_bytes):
        raise ValueError('map source hash mismatch')
    if packet.get('review_sha256') != sha256(review_bytes):
        raise ValueError('roadway and device review hash mismatch')
    try:
        review = json.loads(review_bytes)
    except (ValueError, UnicodeDecodeError, TypeError) as exc:
        raise ValueError('roadway and device review is not structured source') from exc
    if (review.get('schema') != 'median-signal-site-review-v1' or
            review.get('map_sha256') != packet.get('map_sha256') or
            review.get('crossing_id') != packet.get('crossing_id') or
            not review.get('reviewer') or not review.get('source_refs')):
        raise ValueError('reviewed crossing source/provenance absent')
    highway = review.get('highway_review', {})
    if (highway.get('ego') != packet.get('ego_highway') or
            highway.get('other') != packet.get('other_highway') or
            highway.get('public_access') is not True or
            highway.get('public_dedication') is not True):
        raise ValueError('public and different-highway premise unreviewed')
    scope = review.get('driver_scope', {})
    if scope.get('human_driver') is not True or scope.get('conventional_motor_vehicle') is not True:
        raise ValueError('human conventional motor driver scope unreviewed')
    device = review.get('device_review', {})
    inventory = packet.get('official_device_inventory')
    first_device = inventory[0] if isinstance(inventory, list) and inventory else {}
    if (device.get('id') != first_device.get('id') or
            device.get('type') != 'traffic_light' or
            device.get('official') is not True or
            device.get('controls_crossing') is not True or
            device.get('operative_status') != 'operative'):
        raise ValueError('operative official signal control unreviewed')
    if packet.get('cell_id') != 'C125751' or packet.get('law_id') != 'NRS-484B-250-1':
        raise ValueError('wrong cell or law')
    if packet.get('driver_scope_reviewed') is not True:
        raise ValueError('conventional driver scope not reviewed')
    if packet.get('crossing_id') is None or not packet.get('official_device_inventory'):
        raise ValueError('crossing/device inventory absent')
    if packet.get('ego_highway') == packet.get('other_highway'):
        raise ValueError('different-highway premise not established')
    box = packet.get('crossing_bounds_xy_m')
    if not isinstance(box, list) or len(box) != 4 or box[0] >= box[2] or box[1] >= box[3]:
        raise ValueError('crossing bounds invalid')
    for party in ('ego', 'other'):
        route = packet.get(f'{party}_route_xy_m')
        if not isinstance(route, list) or len(route) < 3:
            raise ValueError(f'{party} route incomplete')
        if _inside(route[0], box) or _inside(route[-1], box) or not any(_inside(p, box) for p in route[1:-1]):
            raise ValueError(f'{party} route misses declared crossing')
        if not isinstance(packet.get(f'{party}_road_id'), int):
            raise ValueError(f'{party} road ID absent')
    a = [_xy(p) for p in (packet['ego_route_xy_m'][0], packet['ego_route_xy_m'][1])]
    b = [_xy(p) for p in (packet['other_route_xy_m'][0], packet['other_route_xy_m'][1])]
    v = (a[1][0]-a[0][0], a[1][1]-a[0][1])
    w = (b[1][0]-b[0][0], b[1][1]-b[0][1])
    nv, nw = math.hypot(*v), math.hypot(*w)
    if not nv or not nw or abs((v[0]*w[0]+v[1]*w[1])/(nv*nw)) > 0.5:
        raise ValueError('not distinct crossing approaches')
    return packet


def bind_native(world_map, packet: dict, location_factory):
    """Map binding requires exact OpenDRIVE bytes, road IDs and junction reach."""
    if sha256(world_map.to_opendrive().encode()) != packet['map_sha256']:
        raise ValueError('live map differs from reviewed OpenDRIVE')
    routes = {}
    for party in ('ego', 'other'):
        waypoints = []
        for x, y in packet[f'{party}_route_xy_m']:
            wp = world_map.get_waypoint(location_factory(x, y), project_to_road=False)
            if wp is None or math.hypot(wp.transform.location.x-x, wp.transform.location.y-y) > 2:
                raise ValueError(f'{party} route off live lane')
            waypoints.append(wp)
        if waypoints[0].road_id != packet[f'{party}_road_id']:
            raise ValueError(f'{party} approach road differs')
        if not any(w.is_junction for w in waypoints[1:-1]):
            raise ValueError(f'{party} route lacks junction')
        for first, second in zip(waypoints, waypoints[1:]):
            if not _forward_connected(first, second):
                raise ValueError(f'{party} route disconnected')
        routes[party] = waypoints
    return routes


def construct_native(world, packet: dict, map_bytes: bytes, review_bytes: bytes,
                     location_factory, resolve_device, spawn_vehicle):
    """Validate both Native routes and the live device before actor allocation."""
    validate_source_packet(packet, map_bytes, review_bytes)
    routes = bind_native(world.get_map(), packet, location_factory)
    device_id = packet['official_device_inventory'][0].get('id')
    if not device_id:
        raise ValueError('reviewed device ID missing')
    live_device = resolve_device(world, packet['official_device_inventory'][0])
    if live_device is None or not hasattr(live_device, 'get_state'):
        raise ValueError('reviewed device absent in Native world')
    state = str(live_device.get_state()).split('.')[-1]
    if state not in {'Red', 'Yellow', 'Green'}:
        raise ValueError('live device state unreadable')
    actors = {}
    try:
        for party in ('ego', 'other'):
            actor = spawn_vehicle(party, routes[party][0].transform)
            if actor is None:
                raise ValueError(f'{party} spawn failed')
            actors[party] = actor
    except Exception:
        for actor in reversed(list(actors.values())):
            actor.destroy()
        raise
    return {'routes': routes, 'actors': actors, 'device': live_device,
            'initial_light_readback': state}


def _forward_connected(first, second):
    pending, seen = [first], set()
    for index in range(1200):
        if index >= len(pending):
            break
        wp = pending[index]
        p = wp.transform.location
        key = (wp.road_id, wp.lane_id, round(p.x, 1), round(p.y, 1))
        if key in seen:
            continue
        seen.add(key)
        target = second.transform.location
        if index and wp.road_id == second.road_id and wp.lane_id == second.lane_id and math.hypot(p.x-target.x, p.y-target.y) <= 2:
            return True
        pending.extend(wp.next(2.0))
    return False


def controller_request(ego_before: bool, other_entered: bool, other_cleared: bool,
                       light_readback: str | None, fresh: bool, require_other_first=True):
    """Engineering action only; the official-device exception is not adjudicated."""
    if not fresh or light_readback not in {'Red', 'Yellow', 'Green'}:
        return 'brake'
    if light_readback in {'Red', 'Yellow'}:
        return 'brake'
    if ego_before and require_other_first and (not other_entered or not other_cleared):
        return 'brake'
    return 'proceed'

"""Independent original-frame median-crossing evidence audit.

This consumes a sealed Native packet after capture; authored signal settings are
never substituted for per-frame readback or legal device review.
"""
from __future__ import annotations

import hashlib
import json
import math
import argparse
from pathlib import Path
from signal_crossing import _inside


def _orientation(a, b, c):
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])


def _on_segment(a, b, c):
    return (min(a[0], b[0]) <= c[0] <= max(a[0], b[0]) and
            min(a[1], b[1]) <= c[1] <= max(a[1], b[1]))


def _segments_touch(a, b, c, d):
    ab_c, ab_d = _orientation(a, b, c), _orientation(a, b, d)
    cd_a, cd_b = _orientation(c, d, a), _orientation(c, d, b)
    if ab_c * ab_d < 0 and cd_a * cd_b < 0:
        return True
    return ((ab_c == 0 and _on_segment(a, b, c)) or
            (ab_d == 0 and _on_segment(a, b, d)) or
            (cd_a == 0 and _on_segment(c, d, a)) or
            (cd_b == 0 and _on_segment(c, d, b)))


def _point_in_polygon(point, polygon):
    x, y = point
    inside = False
    for a, b in zip(polygon, polygon[1:] + polygon[:1]):
        if _orientation(a, b, point) == 0 and _on_segment(a, b, point):
            return True
        if (a[1] > y) != (b[1] > y):
            crossing_x = a[0] + (y - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
            if x < crossing_x:
                inside = not inside
    return inside


def _body_overlaps(body, box):
    if not isinstance(body, list) or len(body) < 3:
        raise ValueError('Native body outline absent')
    if any(not isinstance(p, list) or len(p) != 2 or
           any(not isinstance(v, (int, float)) or not math.isfinite(v) for v in p)
           for p in body):
        raise ValueError('Native body outline invalid')
    poly = [tuple(p) for p in body]
    if abs(sum(a[0] * b[1] - b[0] * a[1]
               for a, b in zip(poly, poly[1:] + poly[:1]))) < 1e-8:
        raise ValueError('Native body outline degenerate')
    x0, y0, x1, y1 = box
    corners = [(x0, y0), (x1, y0), (x1, y1), (x0, y1)]
    if any(_inside(p, box) for p in poly) or any(_point_in_polygon(p, poly) for p in corners):
        return True
    return any(_segments_touch(a, b, c, d)
               for a, b in zip(poly, poly[1:] + poly[:1])
               for c, d in zip(corners, corners[1:] + corners[:1]))


def audit(packet: dict, payload: bytes, expected_case: str, expected_source_sha: str):
    if hashlib.sha256(payload).hexdigest() != packet.get('payload_sha256'):
        raise ValueError('Native history seal mismatch')
    if packet.get('case_id') != expected_case or packet.get('review_sha256') != expected_source_sha:
        raise ValueError('case or reviewed source differs')
    history = json.loads(payload)
    rows = history.get('frames', [])
    if len(rows) != packet.get('expected_frames') or len(rows) < 2:
        raise ValueError('original-frame history absent or duration incomplete')
    if history.get('map_sha256') != packet.get('map_sha256'):
        raise ValueError('Native map source differs')
    if packet.get('duration_frames') != packet.get('expected_frames'):
        raise ValueError('duration and original frame count differ')
    if history.get('crossing_id') != packet.get('crossing_id'):
        raise ValueError('Native crossing identity differs')
    bounds = history.get('crossing_bounds_xy_m')
    if (not isinstance(bounds, list) or len(bounds) != 4 or
            any(not isinstance(v, (int, float)) or not math.isfinite(v) for v in bounds) or
            bounds[0] >= bounds[2] or bounds[1] >= bounds[3]):
        raise ValueError('crossing geometry absent')
    entered = {'ego': None, 'other': None}
    cleared = {'ego': None, 'other': None}
    prior_t = None
    prior_inside = {'ego': False, 'other': False}
    states = set()
    transitions = []
    previous_light = None
    for i, row in enumerate(rows):
        if row.get('frame') != i or not isinstance(row.get('time_s'), (int, float)) or not math.isfinite(row['time_s']) or (prior_t is not None and (row['time_s'] <= prior_t or abs(row['time_s'] - prior_t - .05) > .01)):
            raise ValueError('frame/time discontinuity')
        prior_t = row['time_s']
        light = row.get('ego_light_readback')
        if light not in {'Red', 'Yellow', 'Green'}:
            raise ValueError('signal readback absent')
        states.add(light)
        if light != previous_light:
            transitions.append({'frame': i, 'state': light})
        previous_light = light
        for party in ('ego', 'other'):
            actor = row.get(party)
            if not isinstance(actor, dict) or actor.get('actor_id') != history.get(f'{party}_actor_id') or actor.get('alive') is not True:
                raise ValueError(f'{party} Native actor absent or replaced')
            pos = actor.get('xy_m')
            if not isinstance(pos, list) or len(pos) != 2 or not all(isinstance(v, (int, float)) and math.isfinite(v) for v in pos):
                raise ValueError(f'{party} position absent')
            inside = _body_overlaps(actor.get('body_vertices_xy_m'), bounds)
            if i == 0 and inside:
                raise ValueError(f'{party} begins inside crossing')
            if inside and not prior_inside[party] and entered[party] is None:
                entered[party] = i
            if not inside and prior_inside[party] and cleared[party] is None:
                cleared[party] = i
            if inside and cleared[party] is not None:
                raise ValueError(f'{party} reenters crossing after clearance')
            prior_inside[party] = inside
    if any(v is None for v in entered.values()) or any(v is None for v in cleared.values()):
        raise ValueError('crossing entry and clearance unobserved')
    fixed = ('map_sha256', 'review_sha256', 'crossing_id', 'ego_route_sha256',
             'other_route_sha256', 'camera_plan_sha256', 'duration_frames',
             'ego_blueprint', 'other_blueprint')
    if any(not packet.get(key) for key in fixed):
        raise ValueError('comparison source or fixed condition absent')
    return {'case_id': expected_case, 'source_sha256': expected_source_sha,
            **{key: packet[key] for key in fixed},
            'ego_entry_frame': entered['ego'], 'other_entry_frame': entered['other'],
            'ego_clear_frame': cleared['ego'], 'other_clear_frame': cleared['other'],
            'other_entered_first': entered['other'] < entered['ego'],
            'signal_states_observed': sorted(states),
            'signal_initial_state': rows[0]['ego_light_readback'],
            'signal_transition_frames': transitions,
            'physical_review_pending': True}


def main():
    parser = argparse.ArgumentParser(description='Audit sealed original Native frames')
    parser.add_argument('--packet', type=Path, required=True)
    parser.add_argument('--payload', type=Path, required=True)
    parser.add_argument('--case', required=True)
    parser.add_argument('--source-sha256', required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    report = audit(json.loads(args.packet.read_text()), args.payload.read_bytes(),
                   args.case, args.source_sha256)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(report, indent=2) + '\n')


if __name__ == '__main__':
    main()

